package com.fitnutri.backend.capabilities;
import com.fitnutri.backend.ai.*;
import com.fitnutri.backend.common.ZoneResolver;
import com.fitnutri.backend.profile.UserProfileRepository;
import com.fitnutri.backend.support.TestDatabase;
import com.fitnutri.backend.user.User;
import org.junit.jupiter.api.Test;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class CapabilitiesRepositoryIntegrationTest {
    private JdbcTemplate jdbc(TestDatabase db){return new JdbcTemplate(new DriverManagerDataSource(db.url(),db.username(),db.password()));}
    private CapabilitiesResponse response(CapabilitiesRepository repository){var u=new User();u.setId(41L);return new CapabilitiesService(repository,mock(UserProfileRepository.class),new AiFeatureConfiguration("","","","","",false,false,false,false),mock(AiFeatureRegistry.class),new ZoneResolver("Australia/Sydney")).getCapabilities(u);}
    private long foodDataset(JdbcTemplate jdbc){return jdbc.queryForObject("INSERT INTO food_dataset(name,release_name,revision,source_url,content_sha256,nutrient_policy,verified) VALUES('SYNTHETIC_CAPABILITY_ONLY','test','one','https://example.test/synthetic',repeat('a',64),'CORE4_REQUIRED',true) RETURNING id",Long.class);}
    @Test void unverifiedLegacyActiveRowsNeverBecomeReady() throws Exception {try(var db=TestDatabase.create()){db.flyway().migrate();var jdbc=jdbc(db);var repository=new CapabilitiesRepository(jdbc);jdbc.update("INSERT INTO food_reference(dataset_id,public_food_key,food_name,display_name,is_active) SELECT id,'SYNTHETIC_UNVERIFIED','Synthetic','Synthetic',true FROM food_dataset WHERE name='LEGACY_AFCD_UNVERIFIED'");jdbc.update("UPDATE exercise_type SET is_active=true WHERE id=1");var result=response(repository);assertFalse(result.catalogues().food().ready());assertFalse(result.catalogues().food().verified());assertFalse(result.catalogues().exercise().ready());assertFalse(result.catalogues().exercise().verified());}}
    @Test void verifiedButIncompleteRowsAreExcludedFromUsableMembership() throws Exception {try(var db=TestDatabase.create()){db.flyway().migrate();var jdbc=jdbc(db);long dataset=foodDataset(jdbc);jdbc.update("INSERT INTO food_reference(dataset_id,public_food_key,food_name,display_name,energy_kj_100g,protein_g_100g,fat_g_100g,carbs_g_100g,is_active) VALUES(?,'SYNTHETIC_COMPLETE','Synthetic complete','Synthetic complete',0,0,0,0,true)",dataset);jdbc.update("INSERT INTO food_reference(dataset_id,public_food_key,food_name,display_name,is_active) VALUES(?,'SYNTHETIC_INCOMPLETE','Synthetic incomplete','Synthetic incomplete',true)",dataset);var repository=new CapabilitiesRepository(jdbc);assertEquals(2,repository.food().verifiedCount());assertEquals(1,repository.food().usableCount());assertTrue(response(repository).catalogues().food().ready());long activity=jdbc.queryForObject("INSERT INTO activity_dataset(name,release_name,revision,source_url,content_sha256,min_age,max_age,verified) VALUES('SYNTHETIC_CAPABILITY_ONLY','test','one','https://example.test/synthetic',repeat('b',64),19,59,true) RETURNING id",Long.class);jdbc.update("INSERT INTO exercise_type(dataset_id,activity_key,display_name,source_activity_code,source_description,met_value,is_active) VALUES(?,'synthetic-complete','Synthetic complete','99901','Synthetic only',3.5,true)",activity);jdbc.update("INSERT INTO exercise_type(dataset_id,activity_key,display_name,met_value,is_active) VALUES(?,'synthetic-incomplete','Synthetic incomplete',3.5,true)",activity);assertEquals(2,repository.exercise().verifiedCount());assertEquals(1,repository.exercise().usableCount());}}
    @Test void partialVersionIsInvisibleAndRollbackCannotAdvertiseReady() throws Exception {try(var db=TestDatabase.create()){db.flyway().migrate();var repository=new CapabilitiesRepository(jdbc(db));try(var connection=db.connect();var statement=connection.createStatement()){connection.setAutoCommit(false);statement.execute("INSERT INTO food_dataset(id,name,release_name,revision,source_url,content_sha256,nutrient_policy,verified) VALUES(99,'SYNTHETIC_PENDING','test','one','https://example.test/synthetic',repeat('a',64),'CORE4_REQUIRED',true)");statement.execute("INSERT INTO food_reference(dataset_id,public_food_key,food_name,display_name,energy_kj_100g,protein_g_100g,fat_g_100g,carbs_g_100g,is_active) VALUES(99,'SYNTHETIC_PENDING','Synthetic pending','Synthetic pending',0,0,0,0,true)");assertFalse(response(repository).catalogues().food().ready());assertThrows(java.sql.SQLException.class,()->statement.execute("INSERT INTO food_reference(dataset_id,public_food_key,food_name,display_name,energy_kj_100g,is_active) VALUES(99,'SYNTHETIC_BAD','Synthetic invalid','Synthetic invalid',-1,true)"));connection.rollback();}assertFalse(response(repository).catalogues().food().ready());assertEquals(0,repository.food().verifiedCount());}}
    @Test void activeMembershipChangeProducesNewRevisionWithoutMutatingImmutableSource() throws Exception {try(var db=TestDatabase.create()){db.flyway().migrate();var jdbc=jdbc(db);long dataset=foodDataset(jdbc);jdbc.update("INSERT INTO food_reference(dataset_id,public_food_key,food_name,display_name,energy_kj_100g,protein_g_100g,fat_g_100g,carbs_g_100g,is_active) VALUES(?,'SYNTHETIC_A','Synthetic A','Synthetic A',0,0,0,0,true),(?,'SYNTHETIC_B','Synthetic B','Synthetic B',0,0,0,0,true)",dataset,dataset);var repository=new CapabilitiesRepository(jdbc);String before=response(repository).catalogueRevision();jdbc.update("UPDATE food_reference SET is_active=false WHERE public_food_key='SYNTHETIC_A'");var after=response(repository);assertNotEquals(before,after.catalogueRevision());assertTrue(after.catalogues().food().ready());assertEquals("a".repeat(64),jdbc.queryForObject("SELECT content_sha256 FROM food_dataset WHERE id=?",String.class,dataset));}}
}
